class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        nums = [0] + nums + [float('inf')]
        n = len(nums)
        i = 0
        j = n - 1
        l = 0
        r = 0
        res = 0

        while i < n - 1:
            if nums[i] >= nums[i + 1]:
                i = n - 1
            else:
                i += 1

        j = n - 1
        while j > 0:
            if nums[j - 1] >= nums[j]:
                j = 0
            else:
                j -= 1

        l = 0
        r = j
        while l <= i:
            while r < n and nums[l] >= nums[r]:
                r += 1
            r += 1
            res += n - r
            l += 1

        return res
